from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from typing import Any


_CENT = Decimal("0.01")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal("0")


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated = dict(order)

    if new_status == "X":
        updated["STAT_CD"] = "X"
        return updated, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated, [], []

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]
    status = order.get("STAT_CD")

    if status in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _numeric(line.get("QTY"))
        unit_price = _numeric(line.get("UNIT_PRC"))
        extended = _round_cents(quantity * unit_price)
        line["EXT_AMT"] = float(extended)
        total += extended

    discount = _numeric(order.get("DISC_PCT"))
    discounted = _round_cents(total * (Decimal("100") - discount) / Decimal("100"))

    stored_total = _numeric(order.get("TOT_AMT"))
    audits = ["ORD_RETOTAL"] if stored_total != discounted else []

    updated_order["TOT_AMT"] = float(discounted)
    return updated_order, updated_lines, audits
